import sys


def L(n):
    if n < 0x80:
        return bytes([n])
    b = []
    while n:
        b.insert(0, n & 0xFF)
        n >>= 8
    return bytes([0x80 | len(b)]) + bytes(b)


def T(tag, content):
    return bytes([tag]) + L(len(content)) + content


def SEQ(*items):
    return T(0x30, b"".join(items))


def SET(*items):
    return T(0x31, b"".join(items))


def INT(n):
    b = []
    x = n
    while True:
        b.insert(0, x & 0xFF)
        x >>= 1
        if x == 0:
            break
    if b[0] & 0x80:
        b.insert(0, 0)
    return T(0x02, bytes(b))


def OID(raw):
    # raw = already-encoded content bytes
    return T(0x06, raw)


def oid_text(arcs):
    """encode dotted arcs into OID content"""
    out = bytearcs_encode(arcs)
    return bytes(out)


def enc_arc(v):
    parts = [v & 0x7F]
    v >>= 7
    while v:
        parts.append(0x80 | (v & 0x7F))
        v >>= 7
    return bytes(reversed(parts))


def bytearcs_encode(arcs):
    a = list(arcs)
    first = 40 * a[0] + a[1]
    out = bytearray(enc_arc(first))
    for x in a[2:]:
        out += enc_arc(x)
    return bytes(out)


