        subject = name(SET(atv(CN, UTF8("ok"))))
        issuer = name(SET(atv_raw_oid(b"\x80\x37\x03", UTF8("x"))))
        return cert(subject, issuer)
    if kind == "nonmin_late":
        subject = name(SET(atv_raw_oid(b"\x55\x80\x03", UTF8("x"))))
        issuer = name(SET(atv(CN, UTF8("ca"))))
        return cert(subject, issuer)
    if kind == "known":
        subject = name(
            SET(atv(C, PRINT("CN"))),
            SET(atv(O, UTF8("示例公司"))),
            SET(atv(CN, UTF8("example.com"))),
        )
        issuer = subject
        return cert(subject, issuer)
    raise SystemExit("unknown kind")


if __name__ == "__main__":
    sys.stdout.buffer.write(build(sys.argv[1]))

